@import "@fontsource-variable/manrope";
@import "@fontsource-variable/geist-mono";

/* Faithful mode: warm paper page (#f5f1ee), white cards, pure black text and hairlines,
   one hot orange (#ff5e2b) with black text on it. The gradient heading runs from the
   highlight (amber #ffa41c) to the glow (red #ff362a). */
:root {
  --background: oklch(0.9614 0.0055 56.4);
  --foreground: oklch(0 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0 0 0);
  --primary: oklch(0.6869 0.2018 37.6);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.9221 0.0055 56.4);
  --secondary-foreground: oklch(0 0 0);
  --muted: oklch(0.9221 0.0055 56.4);
  --muted-foreground: oklch(0.6413 0.0136 31.5);
  --accent: oklch(1 0 0 / 55%);
  --accent-foreground: oklch(0 0 0);
  --destructive: oklch(0.5608 0.2087 27.2);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0 0 0 / 30%);
  --input: oklch(0 0 0 / 30%);
  --ring: oklch(0.6869 0.2018 37.6);
  --highlight: oklch(0.7972 0.1696 69.5);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.6528 0.2346 30.1);
  --chart-1: oklch(0.6869 0.2018 37.6);
  --chart-2: oklch(0.7972 0.1696 69.5);
  --chart-3: oklch(0.6528 0.2346 30.1);
  --chart-4: oklch(0.5181 0.2501 267.4);
  --chart-5: oklch(0.6413 0.0136 31.5);
  --sidebar: oklch(0.9614 0.0055 56.4);
  --sidebar-foreground: oklch(0 0 0);
  --sidebar-primary: oklch(0.6869 0.2018 37.6);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.9221 0.0055 56.4);
  --sidebar-accent-foreground: oklch(0 0 0);
  --sidebar-border: oklch(0 0 0 / 15%);
  --sidebar-ring: oklch(0.6869 0.2018 37.6);

  --typeface-body: "Manrope Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: var(--typeface-body);
  --typeface-mono: "Geist Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 90rem;
  --page-gutter: clamp(1.3rem, 2.78vw, 2.5rem);
  --section-y: clamp(4.5rem, 8.5vw, 7.5rem);
}

/* Dark sibling (and what the black panels use): pure black page, warm graphite cards
   (#241f1f), white text and white hairlines, the same orange. */
.dark {
  --background: oklch(0 0 0);
  --foreground: oklch(1 0 0);
  --card: oklch(0.2386 0.0088 17.5);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.2386 0.0088 17.5);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.6869 0.2018 37.6);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(1 0 0 / 10%);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.3434 0.0115 17.6);
  --muted-foreground: oklch(0.6413 0.0136 31.5);
  --accent: oklch(1 0 0 / 10%);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.6528 0.2346 30.1);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 30%);
  --input: oklch(1 0 0 / 30%);
  --ring: oklch(0.6869 0.2018 37.6);
  --highlight: oklch(0.7972 0.1696 69.5);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.6528 0.2346 30.1);
  --chart-1: oklch(0.6869 0.2018 37.6);
  --chart-2: oklch(0.7972 0.1696 69.5);
  --chart-3: oklch(0.6528 0.2346 30.1);
  --chart-4: oklch(0.6 0.2 267);
  --chart-5: oklch(0.6413 0.0136 31.5);
  --sidebar: oklch(0.145 0.004 20);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.6869 0.2018 37.6);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.2386 0.0088 17.5);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 15%);
  --sidebar-ring: oklch(0.6869 0.2018 37.6);
}
